const items = $input.all();
return items.map((item) => {
  const src = item.json ?? {};
  const content = String(src.content ?? src.text ?? '').trim();
  const timestamp = src.timestamp ?? new Date().toISOString();
  const whatsappNumber = String(src.whatsapp_number ?? src.sender_id ?? '').replace(/\D/g, '');
  const chatId = String(src.chat_id ?? whatsappNumber);
  const messageType = src.message_type ?? (content ? 'text' : 'unknown');

  return {
    json: {
      ...src,
      client_id: src.client_id ?? null,
      client_code: src.client_code ?? 'vivi',
      chat_id: chatId,
      sender_id: String(src.sender_id ?? chatId),
      whatsapp_number: whatsappNumber,
      message_type: messageType,
      content,
      clean_text: content.toLowerCase().replace(/\s+/g, ' ').trim(),
      timestamp,
      direction: 'inbound',
      session_name: src.session_name ?? ['vivi', whatsappNumber || 'unknown'].filter(Boolean).join('_'),
      raw_payload: src.raw_payload ?? src,
    },
  };
});

const leadFromCreate = $input.first()?.json ?? {};
const base = $('Vivi_Guard_Processing').first().json;
return [{
  json: {
    ...base,
    ...(leadFromCreate.id ? { lead_id: leadFromCreate.id, lead_exists: true } : {}),
    current_state: 'PROCESSING',
    session_locked: true,
  },
}];

const base = $('Vivi_Lock_Session').first().json;
const text = String(base.clean_text ?? '').toLowerCase();
const has = (...terms) => terms.some((term) => text.includes(term));

let intent = 'knowledge';
if (has('jadwal', 'jam buka', 'jam berapa', 'schedule', 'kelas hari', 'hari ini')) intent = 'schedule';
else if (has('harga', 'biaya', 'price', 'tarif', 'promo')) intent = 'price';
else if (has('program', 'kelas', 'paket', 'latihan', 'course')) intent = 'program';
else if (has('daftar', 'join', 'gabung', 'registrasi', 'trial')) intent = 'join';

return [{
  json: {
    ...base,
    intent,
    is_schedule: intent === 'schedule',
    is_price: intent === 'price',
    is_program: intent === 'program',
    is_join: intent === 'join',
    is_knowledge: intent === 'knowledge',
    extracted_topic: text,
  },
}];

return $input.all().map((item) => {
  const text = String(item.json.response_text ?? '').trim();
  const friendly = text.startsWith('Hai')
    ? text
    : 'Hai kak, berikut info dari VIVI.\\n\\n' + text + '\\n\\nKalau masih ada yang mau ditanyakan, balas chat ini saja ya.';
  return { json: { ...item.json, styled_response_text: friendly } };
});

return $input.all().map((item) => {
  const replyText = String(item.json.styled_response_text ?? item.json.response_text ?? '').trim();
  return {
    json: {
      ...item.json,
      reply_text: replyText || 'Hai kak, pesan sudah kami terima. Tim kami akan follow up secepatnya ya.',
      current_state: 'WAITING_REPLY',
    },
  };
});

return $input.all().map((item) => ({
  json: {
    ...item.json,
    lookup_type: 'knowledge',
    search_terms: String(item.json.clean_text ?? '').split(' ').filter(Boolean),
  },
}));

return $input.all().map((item) => ({
  json: {
    ...item.json,
    knowledge_keywords: item.json.search_terms.slice(0, 6),
  },
}));

return $input.all().map((item) => {
  const text = String(item.json.clean_text ?? '').toLowerCase();

  const areas = [
    { key: 'kepanjen', club: 'Step Up', aliases: ['kepanjen', 'kepanjen malang'] },
    { key: 'tidar', club: 'Fitclub', aliases: ['tidar', 'tidar malang'] },
    { key: 'dinoyo', club: 'Shape Up', aliases: ['dinoyo', 'dinoyo malang'] },
  ];

  const matchedArea = areas.find((area) => area.aliases.some((alias) => text.includes(alias))) ?? null;

  return {
    json: {
      ...item.json,
      lookup_type: 'schedule',
      schedule_area: matchedArea?.key ?? null,
      schedule_area_label: matchedArea ? matchedArea.key.charAt(0).toUpperCase() + matchedArea.key.slice(1) : null,
      schedule_club_name: matchedArea?.club ?? null,
      has_schedule_match: Boolean(matchedArea),
      schedule_prompt_options: ['Kepanjen', 'Tidar', 'Dinoyo'],
    },
  };
});

return $input.all().map((item) => ({
  json: {
    ...item.json,
    schedule_query: [item.json.schedule_area, item.json.schedule_club_name].filter(Boolean).join(' ').trim(),
    schedule_area_text: item.json.schedule_area_label ?? null,
  },
}));

return $input.all().map((item) => {
  const text = String(item.json.clean_text ?? '');
  const sport = ['renang', 'basket', 'futsal', 'badminton', 'gym', 'tenis'].find((name) => text.includes(name)) ?? 'umum';
  return { json: { ...item.json, lookup_type: 'price', sport_keyword: sport } };
});

return $input.all().map((item) => ({
  json: {
    ...item.json,
    has_price_match: Boolean(item.json.sport_keyword),
    price_query: [item.json.sport_keyword, item.json.clean_text].filter(Boolean).join(' '),
  },
}));

const base = $('vivi_normalize_schedule').first().json;
const rows = $input.all().map((item) => item.json);
const targetArea = String(base.schedule_area ?? '').toLowerCase();

const match = rows.find((row) => {
  const lokasi = String(row.lokasi_club ?? row['lokasi_club'] ?? '').toLowerCase();
  const club = String(row.nama_club ?? row['nama_club'] ?? '').toLowerCase();
  return lokasi.includes(targetArea) || club.includes(targetArea);
}) ?? null;

if (!match) {
  return [{
    json: {
      ...base,
      matched_row: null,
      schedule_media_url: null,
      response_text: 'Maaf kak, jadwal untuk area ' + (base.schedule_area_label ?? 'tersebut') + ' belum tersedia saat ini. Kalau mau, kakak bisa pilih area lain: Kepanjen, Tidar, atau Dinoyo.',
    },
  }];
}

const clubName = String(match.nama_club ?? match['nama_club'] ?? '').trim();
const lokasiClub = String(match.lokasi_club ?? match['lokasi_club'] ?? '').trim();
const jadwalUrl = String(match.jadwal_club ?? match['jadwal_club'] ?? '').trim();
const isUsableUrl = jadwalUrl && jadwalUrl.toLowerCase() !== 'none';
const areaLabel = base.schedule_area_label ?? lokasiClub.split('-')[0].trim() ?? 'area tersebut';

const responseText = isUsableUrl
  ? 'Baik kak, untuk area ' + areaLabel + ' jadwalnya sebagai berikut ya kak.\n\nClub: ' + clubName + '\nLokasi: ' + lokasiClub + '\nJadwal: ' + jadwalUrl
  : 'Baik kak, untuk area ' + areaLabel + ' saat ini datanya ada di club ' + clubName + ', tetapi link gambar jadwalnya belum tersedia ya kak.';

return [{
  json: {
    ...base,
    matched_row: match,
    schedule_media_url: isUsableUrl ? jadwalUrl : null,
    schedule_club_name: clubName,
    schedule_location: lokasiClub,
    response_text: responseText,
  },
}];

const base = $('vivi_normalize_price').first().json;
const rows = $input.all().map((item) => item.json);
const match = rows.find((row) => JSON.stringify(row).toLowerCase().includes(base.sport_keyword)) ?? rows[0] ?? null;
const response = match
  ? 'Harga yang saya temukan untuk ' + base.sport_keyword + ': ' + JSON.stringify(match)
  : 'Maaf, data harga untuk ' + base.sport_keyword + ' belum tersedia di sheet saat ini.';
return [{ json: { ...base, matched_row: match, response_text: response } }];

const base = $('vivi_normalize_knowledge').first().json;
const rows = $input.all().map((item) => item.json);
const keywords = (base.knowledge_keywords ?? []).map((term) => String(term).toLowerCase());
const match = rows.find((row) => keywords.some((term) => JSON.stringify(row).toLowerCase().includes(term))) ?? rows[0] ?? null;
const response = match
  ? 'Informasi yang saya temukan: ' + JSON.stringify(match)
  : 'Saya belum menemukan jawaban yang pas di knowledge base. Boleh jelaskan lagi pertanyaannya dengan sedikit lebih spesifik?';
return [{ json: { ...base, matched_row: match, response_text: response } }];

return $input.all().map((item) => ({
  json: {
    ...item.json,
    lookup_type: 'program',
    search_terms: String(item.json.clean_text ?? '').split(' ').filter(Boolean),
  },
}));

return $input.all().map((item) => ({
  json: {
    ...item.json,
    program_keywords: item.json.search_terms.slice(0, 6),
  },
}));

const base = $('vivi_normalize_program').first().json;
const rows = $input.all().map((item) => item.json);
const keywords = (base.program_keywords ?? []).map((term) => String(term).toLowerCase());
const match = rows.find((row) => keywords.some((term) => JSON.stringify(row).toLowerCase().includes(term))) ?? rows[0] ?? null;
const response = match
  ? 'Program yang paling relevan saya temukan seperti ini: ' + JSON.stringify(match)
  : 'Saat ini saya belum menemukan detail program yang sesuai. Boleh kirim kata kunci yang lebih spesifik?';
return [{ json: { ...base, matched_row: match, response_text: response } }];

return $input.all().map((item) => ({
  json: {
    ...item.json,
    lookup_type: 'join',
    join_interest: item.json.clean_text,
  },
}));

return $input.all().map((item) => ({
  json: {
    ...item.json,
    response_text: 'Siap, untuk proses pendaftaran kamu bisa isi form ini dulu ya: ' + item.json.join_form_link,
  },
}));

return $input.all().map((item) => ({
  json: {
    ...item.json,
    needs_registration_form: true,
  },
}));

return $input.all().map((item) => ({
  json: {
    ...item.json,
    join_form_link: 'https://example.com/vivi-registration',
  },
}));

return $input.all().map((item) => ({
  json: {
    ...item.json,
    session_unlocked: true,
  },
}));

return $input.all().map((item) => ({
  json: {
    ...item.json,
    route_reason: 'Keyword classifier selected the most likely intent.',
  },
}));

const base = $('Vivi_Normalize_Message').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row && Object.keys(row).length > 0);
const lead = rows[0] ?? null;
const currentState = String(lead?.current_state ?? 'NEW').toUpperCase();
const isLocked = ['PROCESSING', 'WAITING_REPLY'].includes(currentState);

return [{
  json: {
    ...base,
    lead,
    lead_exists: Boolean(lead?.id),
    lead_id: lead?.id ?? null,
    current_state: currentState,
    needs_lead_creation: !lead?.id,
    is_locked: isLocked,
    should_notify_new_lead: !lead?.id,
  },
}];

return $input.all().map((item) => {
  const responseText = String(item.json.response_text ?? '').trim();
  const fallback = 'Terima kasih, pesanmu sudah masuk. Tim VIVI akan bantu cek dan membalas secepatnya.';
  return {
    json: {
      ...item.json,
      response_text: responseText || fallback,
    },
  };
});

const base = $('vivi_normalize_schedule').first().json;
return [{
  json: {
    ...base,
    response_text: 'Baik kak, untuk jadwal boleh pilih area dulu ya kak: Kepanjen, Tidar, atau Dinoyo?',
  },
}];

return $input.all().map((item) => ({
  json: {
    ...item.json,
    notification_skipped: true,
    notification_note: 'Sub-workflow notification disabled in publish-safe version. Publish or rebuild notification flow separately if still needed.',
  },
}));
